	    public void EncodeBase64NVARCHARFields(ShipmentComputedFieldsPM entityPM)
        {
            if (String.IsNullOrWhiteSpace(entityPM.EncodeBase64NVARCHARFieldsBy)) 
            {
                return;
            }
            if (!String.IsNullOrWhiteSpace(entityPM.ContainersNumbers)) //T4 find type == nText 
            {
                entityPM.ContainersNumbers = Encoding.GetEncoding(entityPM.EncodeBase64NVARCHARFieldsBy).GetString(Convert.FromBase64String(entityPM.ContainersNumbers));
            }
            if (!String.IsNullOrWhiteSpace(entityPM.FirstPickupLocation)) //T4 find type == nText 
            {
                entityPM.FirstPickupLocation = Encoding.GetEncoding(entityPM.EncodeBase64NVARCHARFieldsBy).GetString(Convert.FromBase64String(entityPM.FirstPickupLocation));
            }
            if (!String.IsNullOrWhiteSpace(entityPM.DocumentsSearchFields)) //T4 find type == nText 
            {
                entityPM.DocumentsSearchFields = Encoding.GetEncoding(entityPM.EncodeBase64NVARCHARFieldsBy).GetString(Convert.FromBase64String(entityPM.DocumentsSearchFields));
            }
            if (!String.IsNullOrWhiteSpace(entityPM.MissingDocumentsNames)) //T4 find type == nText 
            {
                entityPM.MissingDocumentsNames = Encoding.GetEncoding(entityPM.EncodeBase64NVARCHARFieldsBy).GetString(Convert.FromBase64String(entityPM.MissingDocumentsNames));
            }
            if (!String.IsNullOrWhiteSpace(entityPM.Commodity)) //T4 find type == nText 
            {
                entityPM.Commodity = Encoding.GetEncoding(entityPM.EncodeBase64NVARCHARFieldsBy).GetString(Convert.FromBase64String(entityPM.Commodity));
            }
            if (!String.IsNullOrWhiteSpace(entityPM.DeliveryNotes)) //T4 find type == nText 
            {
                entityPM.DeliveryNotes = Encoding.GetEncoding(entityPM.EncodeBase64NVARCHARFieldsBy).GetString(Convert.FromBase64String(entityPM.DeliveryNotes));
            }
            if (!String.IsNullOrWhiteSpace(entityPM.PickupNotes)) //T4 find type == nText 
            {
                entityPM.PickupNotes = Encoding.GetEncoding(entityPM.EncodeBase64NVARCHARFieldsBy).GetString(Convert.FromBase64String(entityPM.PickupNotes));
            }
            if (!String.IsNullOrWhiteSpace(entityPM.ContainersNumbersandTypesArray)) //T4 find type == nText 
            {
                entityPM.ContainersNumbersandTypesArray = Encoding.GetEncoding(entityPM.EncodeBase64NVARCHARFieldsBy).GetString(Convert.FromBase64String(entityPM.ContainersNumbersandTypesArray));
            }
            entityPM.EncodeBase64NVARCHARFieldsBy=null;
		}
